(function(){
  "use strict";

  const LOGOS = {
    bfp: "data:image/png;base64,",
    pnp: "data:image/png;base64,",
    mdrrmo: "data:image/jpeg;base64,",
    rhu: "data:image/jpeg;base64,",
    masinloc_hall: "data:image/png;base64,",
    bani_shuttle: "data:image/png;base64,",
    pcg: "data:image/png;base64,"
  };


  /* ---------------- DATA ---------------- */
  const AGENCIES = [
    {
      id:'bfp', name:'Bureau of Fire Protection', short:'BFP', category:'fire', catLabel:'Fire Emergency',
      numbers:['0961-460-0793','0917-115-7956'],
      desc:'Fire suppression, rescue, and fire safety response for Masinloc.'
    },
    {
      id:'pnp', name:'Philippine National Police', short:'PNP', category:'police', catLabel:'Police Assistance',
      numbers:['0998-598-5516'],
      desc:'Law enforcement, crime response, and public safety assistance.'
    },
    {
      id:'mdrrmo', name:'Municipal Disaster Risk Reduction & Management Office', short:'MDRRMO', category:'disaster', catLabel:'Disaster Response',
      numbers:['0921-405-9748'],
      desc:'Disaster monitoring, evacuation coordination, and relief operations.'
    },
    {
      id:'rhu', name:'Rural Health Unit', short:'RHU', category:'medical', catLabel:'Medical Emergency',
      numbers:[' 0947-581-8397'],
      desc:'Emergency medical care, ambulance coordination, and health services.'
    },
    {
      id:'masinloc_hall', name:'Masinloc Municipal Hall', short:'Municipal Hall', category:'government', catLabel:'Government and Community Services',
      numbers:['0917-856-2164','0917-1178-586'],
      desc:'Official hotline for municipal government concerns, public assistance, local announcements, and community services.'
    },
    {
      id:'bani_shuttle', name:'Bani Shuttle Service', short:'Bani Shuttle', category:'transport', catLabel:'Government and Community Services',
      numbers:['0985-306-0129'],
      desc:'Community transportation service for residents requiring local transport assistance.'
    },
    {
      id:'pcg', name:'Philippine Coast Guard', short:'PCG', category:'coastguard', catLabel:'Maritime Emergency',
      numbers:['(02) 8527-3877','0917-724-3682'],
      desc:'Provides maritime safety, search and rescue operations, coastal security, marine environmental protection, and emergency response for sea-related incidents.'
    }
  ];

  AGENCIES.forEach(a => { a.logo = LOGOS[a.id]; });

  const CATEGORY_META = {
    fire:    { label:'Fire',     tag:'tag-fire',     icon:'icon-fire',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/></svg>' },
    police:  { label:'Police',   tag:'tag-police',   icon:'icon-police',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>' },
    medical: { label:'Medical',  tag:'tag-medical',  icon:'icon-medical',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.29 1.51 4.04 3 5.5l7 7z"/><path d="M12 8v4M10 10h4"/></svg>' },
    disaster:{ label:'Disaster', tag:'tag-disaster', icon:'icon-disaster',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><path d="M12 9v4M12 17h.01"/></svg>' },
    government:{ label:'Government', tag:'tag-government', icon:'icon-government',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21h18M4 21V9l8-6 8 6v12M9 21v-6h6v6"/></svg>' },
    transport:{ label:'Transport', tag:'tag-transport', icon:'icon-transport',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 13l1.5-4.5A2 2 0 0 1 6.4 7h11.2a2 2 0 0 1 1.9 1.5L21 13v6a1 1 0 0 1-1 1h-1a1 1 0 0 1-1-1v-1H6v1a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><circle cx="7" cy="16" r="1"/><circle cx="17" cy="16" r="1"/></svg>' },
    coastguard:{ label:'Coast Guard', tag:'tag-coastguard', icon:'icon-coastguard',
      svg:'<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20M8 6h8M5 10h14M3 15c1 1.5 3 1.5 4 0 1 1.5 3 1.5 4 0 1 1.5 3 1.5 4 0 1 1.5 3 1.5 4 0"/><circle cx="12" cy="4" r="2"/></svg>' }
  };

  const TIPS = [
    { id:'fire', title:'Fire safety tips', category:'fire',
      points:[
        'Know two ways out of every room and agree on a family meeting point outside.',
        'Turn off electrical appliances and LPG tanks when not in use.',
        'Stop, drop, and roll if your clothing catches fire — never run.',
        'Keep a fire extinguisher accessible and know how to use it.',
        'Call BFP Masinloc immediately and evacuate calmly, staying low under smoke.'
      ]},
    { id:'disaster', title:'Disaster preparedness tips', category:'disaster',
      points:[
        'Prepare a "go-bag" with water, food, flashlight, first-aid kit, and documents.',
        'Know your barangay\'s evacuation center and route in advance.',
        'Monitor MDRRMO and PAGASA advisories during typhoon season.',
        'Secure loose objects outdoors before a storm arrives.',
        'Charge phones and power banks ahead of expected bad weather.'
      ]},
    { id:'medical', title:'Medical emergency guidelines', category:'medical',
      points:[
        'Check responsiveness and breathing before doing anything else.',
        'Call RHU or the nearest hospital while giving clear, calm details.',
        'Apply firm pressure to control visible bleeding with a clean cloth.',
        'Do not move a person with a suspected spinal injury unless necessary.',
        'Keep the person calm, warm, and monitored until help arrives.'
      ]},
    { id:'flood', title:'Flood and earthquake safety procedures', category:'disaster',
      points:[
        'Flood: Move to higher ground immediately; avoid walking or driving through floodwater.',
        'Flood: Turn off electricity at the main breaker if water is rising indoors.',
        'Earthquake: Drop, cover, and hold on under a sturdy table until shaking stops.',
        'Earthquake: Stay away from windows, glass, and heavy furniture that can fall.',
        'After either event: Check for injuries, gas leaks, and structural damage before re-entering.'
      ]}
  ];

  /* ---------------- STATE (in-memory only — no browser storage in this demo) ---------------- */
  let favorites = new Set(['bfp']);
  let history = [];
  let currentCategory = 'all';
  let lastLocation = null;

  /* ---------------- HELPERS ---------------- */
  function agencyIconSvg(cat){ return CATEGORY_META[cat].svg; }
  function fitModeFor(id){ return id==='rhu' ? 'fit-cover' : 'fit-contain'; }
  function iconBadgeClass(agencyLike){
    return agencyLike && agencyLike.logo ? `has-logo ${fitModeFor(agencyLike.id)}` : iconClass(agencyLike.category);
  }
  function iconBadgeInner(agencyLike){
    return agencyLike && agencyLike.logo ? `<img src="${agencyLike.logo}" alt="${agencyLike.short} logo">` : agencyIconSvg(agencyLike.category);
  }
  const TIP_AGENCY_ID = { fire:'bfp', disaster:'mdrrmo', medical:'rhu', flood:'mdrrmo' };
  function iconClass(cat){ return CATEGORY_META[cat].icon; }
  function tagClass(cat){ return CATEGORY_META[cat].tag; }

  function showToast(msg){
    const t = document.getElementById('toast');
    document.getElementById('toastMsg').textContent = msg;
    t.classList.add('show');
    clearTimeout(showToast._t);
    showToast._t = setTimeout(()=> t.classList.remove('show'), 2600);
  }

  function matchesQuery(agency, q){
    if(!q) return true;
    q = q.toLowerCase();
    return agency.name.toLowerCase().includes(q) ||
           agency.short.toLowerCase().includes(q) ||
           agency.catLabel.toLowerCase().includes(q) ||
           agency.numbers.some(n=> n.toLowerCase().includes(q));
  }

  /* ---------------- CARD RENDERING ---------------- */
  function agencyCardHTML(a, {compact=false} = {}){
    const isFav = favorites.has(a.id);
    return `
    <div class="agency-card" data-agency="${a.id}">
      <span class="cat-tag ${tagClass(a.category)}">${a.catLabel}</span>
      <div class="agency-icon ${iconBadgeClass(a)}">${iconBadgeInner(a)}</div>
      <div>
        <div class="agency-name">${a.short}</div>
        <div class="agency-sub">${a.name}</div>
      </div>
      <div class="agency-numbers">
        ${a.numbers.map(n=>`<div>${n}</div>`).join('')}
      </div>
      <div class="card-actions">
        <button class="call-btn" data-call="${a.id}" data-number="${a.numbers[0]}">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
          Call
        </button>
        <button class="fav-btn ${isFav?'active':''}" data-fav="${a.id}" aria-label="Toggle favorite">
          <svg viewBox="0 0 24 24" fill="${isFav?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
        </button>
      </div>
    </div>`;
  }

  function renderGrid(containerId, list){
    const el = document.getElementById(containerId);
    el.innerHTML = list.map(a=>agencyCardHTML(a)).join('');
  }

  function renderQuickAccess(){
    document.getElementById('quickAccessGrid').innerHTML = AGENCIES.map(a=>agencyCardHTML(a)).join('');
  }

  function renderChips(){
    const cats = ['all', ...Object.keys(CATEGORY_META)];
    const el = document.getElementById('categoryChips');
    el.innerHTML = cats.map(c=>{
      const label = c==='all' ? 'All services' : CATEGORY_META[c].label;
      return `<button class="chip ${currentCategory===c?'active':''}" data-cat="${c}">${label}</button>`;
    }).join('');
  }

  function filterAndRenderDashboard(){
    const q = document.getElementById('dashSearch').value;
    let list = AGENCIES.filter(a=> (currentCategory==='all' || a.category===currentCategory) && matchesQuery(a,q));
    document.getElementById('dashboardGrid').style.display = list.length? '' : 'none';
    document.getElementById('dashEmpty').style.display = list.length? 'none':'';
    renderGrid('dashboardGrid', list);
  }

  function renderSosList(){
    document.getElementById('sosGrid').innerHTML = AGENCIES.map(a=>agencyCardHTML(a)).join('');
    document.getElementById('sosModalList').innerHTML = AGENCIES.map(a=>`
      <div class="sos-row">
        <div class="ic ${iconBadgeClass(a)}">${iconBadgeInner(a)}</div>
        <div class="info">
          <div class="n">${a.short}</div>
          <div class="p">${a.numbers.join(' · ')}</div>
        </div>
        <button class="go" data-call="${a.id}" data-number="${a.numbers[0]}" aria-label="Call ${a.short}">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
        </button>
      </div>`).join('');
  }

  function renderContacts(){
    renderGrid('contactsGrid', AGENCIES);
    const favAgencies = AGENCIES.filter(a=>favorites.has(a.id));
    const favEl = document.getElementById('favList');
    favEl.innerHTML = favAgencies.length ? favAgencies.map(a=>`
      <div class="hist-item">
        <div class="hist-ic ${iconBadgeClass(a)}" style="color:#fff;">${iconBadgeInner(a)}</div>
        <div style="flex:1;">
          <div class="hi-name">${a.short}</div>
          <div class="hi-meta">${a.numbers[0]}</div>
        </div>
        <button class="call-btn" style="width:auto; flex:none; padding:8px 14px;" data-call="${a.id}" data-number="${a.numbers[0]}">Call</button>
      </div>`).join('') : `<div class="empty-state" style="padding:20px 0;"><p>No favorites yet — tap the star on any hotline card.</p></div>`;
    renderHistory();
  }

  function renderHistory(){
    const el = document.getElementById('historyList');
    el.innerHTML = history.length ? history.map(h=>`
      <div class="hist-item">
        <div class="hist-ic ${iconBadgeClass(h)}" style="color:#fff;">${iconBadgeInner(h)}</div>
        <div style="flex:1;">
          <div class="hi-name">${h.short}</div>
          <div class="hi-meta">${h.number} · ${h.time}</div>
        </div>
      </div>`).join('') : `<div class="empty-state" style="padding:20px 0;"><p>No calls yet this session.</p></div>`;
  }

  function renderTips(){
    document.getElementById('tipsAccordion').innerHTML = TIPS.map((t,i)=>{
      const relatedAgency = AGENCIES.find(a=>a.id===TIP_AGENCY_ID[t.id]);
      const cls = relatedAgency ? iconBadgeClass(relatedAgency) : iconClass(t.category);
      const inner = relatedAgency ? iconBadgeInner(relatedAgency) : agencyIconSvg(t.category);
      return `
      <details class="accordion" ${i===0?'open':''}>
        <summary>
          <div class="ic ${cls}">${inner}</div>
          ${t.title}
          <svg class="chev" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
        </summary>
        <div class="acc-body"><ul>${t.points.map(p=>`<li>${p}</li>`).join('')}</ul></div>
      </details>`;
    }).join('');
  }

  /* ---------------- NAVIGATION ---------------- */
  function setActiveView(id){
    document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
    const target = document.getElementById('view-'+id) || document.getElementById('view-home');
    target.classList.add('active');
    document.querySelectorAll('[data-nav]').forEach(n=>{
      n.classList.toggle('active', n.getAttribute('data-nav')===id);
    });
    window.scrollTo({top:0, behavior:'instant' in window ? 'instant':'auto'});
  }

  function route(){
    const id = (location.hash || '#home').slice(1);
    setActiveView(id);
    if(id === 'location' && typeof checkGeoPermission === 'function'){ checkGeoPermission(); }
  }
  window.addEventListener('hashchange', route);

  /* ---------------- THEME ---------------- */
  function applyTheme(mode){
    document.documentElement.setAttribute('data-theme', mode);
    const icon = document.getElementById('themeIcon');
    icon.innerHTML = mode==='dark'
      ? '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>'
      : '<circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>';
  }
  let theme = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  applyTheme(theme);
  document.getElementById('themeToggle').addEventListener('click', ()=>{
    theme = theme==='dark' ? 'light' : 'dark';
    applyTheme(theme);
  });

  /* ---------------- CALL FLOW ---------------- */
  function openCallModal(agencyId, number){
    const a = AGENCIES.find(x=>x.id===agencyId);
    if(!a) return;
    document.getElementById('callModalAgency').textContent = a.short + ' — ' + a.name;
    document.getElementById('callModalNumber').textContent = number;
    document.getElementById('callModalIcon').className = 'mi ' + iconBadgeClass(a);
    document.getElementById('callModalIcon').style.background = '';
    document.getElementById('callModalIcon').innerHTML = a.logo ? iconBadgeInner(a) : agencyIconSvg(a.category).replace('#fff','currentColor');
    const confirmBtn = document.getElementById('callModalConfirm');
    confirmBtn.href = 'tel:' + number.replace(/[^\d+]/g,'');
    confirmBtn.onclick = function(){
      history.unshift({id:a.id, short:a.short, number, category:a.category, logo:a.logo, time: new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})});
      if(history.length>20) history.pop();
      closeOverlay('callOverlay');
      showToast('Calling ' + a.short + '…');
    };
    openOverlay('callOverlay');
  }

  function openOverlay(id){ document.getElementById(id).classList.add('open'); }
  function closeOverlay(id){ document.getElementById(id).classList.remove('open'); }

  document.addEventListener('click', function(e){
    const callBtn = e.target.closest('[data-call]');
    if(callBtn){
      e.preventDefault();
      openCallModal(callBtn.getAttribute('data-call'), callBtn.getAttribute('data-number'));
      return;
    }
    const favBtn = e.target.closest('[data-fav]');
    if(favBtn){
      const id = favBtn.getAttribute('data-fav');
      if(favorites.has(id)){ favorites.delete(id); showToast('Removed from favorites'); }
      else { favorites.add(id); showToast('Added to favorites'); }
      refreshAllRenders();
      return;
    }
    const catChip = e.target.closest('[data-cat]');
    if(catChip){
      currentCategory = catChip.getAttribute('data-cat');
      renderChips();
      filterAndRenderDashboard();
      return;
    }
    if(e.target.closest('[data-open-sos]')){
      e.preventDefault();
      openOverlay('sosOverlay');
      return;
    }
    if(e.target.closest('[data-close-sos]') || e.target.id==='sosOverlay'){
      closeOverlay('sosOverlay');
      return;
    }
    if(e.target.closest('[data-close-call]') || e.target.id==='callOverlay'){
      closeOverlay('callOverlay');
      return;
    }
    const navEl = e.target.closest('[data-nav]');
    if(navEl){
      // let default hash navigation happen; just ensure active state updates promptly
      setTimeout(route, 0);
    }
  });

  document.getElementById('sosSendAlert').addEventListener('click', function(){
    closeOverlay('sosOverlay');
    location.hash = '#location';
    showToast('Opening location sharing…');
  });

  document.getElementById('clearHistory').addEventListener('click', function(){
    history = [];
    renderHistory();
    showToast('Call history cleared');
  });

  /* ---------------- SEARCH ---------------- */
  document.getElementById('homeSearch').addEventListener('input', function(){
    const q = this.value;
    const list = AGENCIES.filter(a=>matchesQuery(a,q));
    renderGrid('quickAccessGrid', list.length?list:AGENCIES);
    if(q){ document.getElementById('dashSearch').value = q; }
  });
  document.getElementById('homeSearch').addEventListener('keydown', function(e){
    if(e.key==='Enter'){ location.hash = '#dashboard'; filterAndRenderDashboard(); }
  });
  document.getElementById('dashSearch').addEventListener('input', filterAndRenderDashboard);

  /* ---------------- LOCATION SHARING ---------------- */
  function setLocStatus(text, isError){
    const el = document.getElementById('locStatus');
    el.querySelector('span').textContent = text;
    el.style.borderColor = isError ? 'var(--red-600)' : 'var(--border)';
    document.getElementById('locRetryWrap').style.display = isError ? '' : 'none';
  }

  function isSecureCtx(){
    return window.isSecureContext === true || location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  }

  let locating = false;
  function setLocBtnLoading(loading){
    const btn = document.getElementById('getLocationBtn');
    const icon = document.getElementById('locBtnIcon');
    const label = document.getElementById('locBtnLabel');
    if(!btn) return;
    btn.disabled = loading;
    btn.style.opacity = loading ? '.7' : '';
    icon.classList.toggle('spin', loading);
    label.textContent = loading ? 'Detecting…' : 'Detect my current location';
  }

  function geoErrorMessage(err){
    switch(err.code){
      case err.PERMISSION_DENIED:
        return "Location access is blocked for this site. On your phone: open your browser's site settings (or Settings > Apps > Browser > Permissions > Location) and allow access, then tap Try again.";
      case err.POSITION_UNAVAILABLE:
        return 'Your location could not be determined. Make sure Location Services/GPS is turned on for your phone and browser, then try again.';
      case err.TIMEOUT:
        return 'Location request took too long. Move to an area with a clearer sky or signal, then try again.';
      default:
        return 'Could not get your location. Please try again.';
    }
  }

  function handleLocation(isRetryLowAccuracy){
    if(locating) return;
    if(!('geolocation' in navigator)){
      setLocStatus('Geolocation is not supported on this device or browser.', true);
      return;
    }
    if(!isSecureCtx()){
      setLocStatus('Location sharing needs a secure (https://) connection. Please reload this page over HTTPS and try again.', true);
      return;
    }
    locating = true;
    setLocBtnLoading(true);
    setLocStatus(isRetryLowAccuracy ? 'Trying a quicker, approximate fix…' : 'Detecting your location — allow the permission prompt if asked…', false);

    const opts = {
      enableHighAccuracy: !isRetryLowAccuracy,
      timeout: isRetryLowAccuracy ? 8000 : 15000,
      maximumAge: 0
    };

    navigator.geolocation.getCurrentPosition(function(pos){
      locating = false;
      setLocBtnLoading(false);
      const {latitude, longitude, accuracy} = pos.coords;
      lastLocation = {lat:latitude, lng:longitude};
      const mapUrl = `https://www.google.com/maps?q=${latitude.toFixed(6)},${longitude.toFixed(6)}`;
      const acc = Math.round(accuracy);
      const accNote = acc > 150 ? ' (approximate — try again outdoors for a tighter fix).' : '.';
      setLocStatus('Location detected — accurate to about ' + acc + ' meters' + accNote, false);
      document.getElementById('locResult').style.display = '';
      document.getElementById('locLinkBox').textContent = mapUrl;
      document.getElementById('openMapBtn').href = mapUrl;
      showToast('Location ready to share');
    }, function(err){
      locating = false;
      setLocBtnLoading(false);
      if(!isRetryLowAccuracy && (err.code === err.TIMEOUT || err.code === err.POSITION_UNAVAILABLE)){
        handleLocation(true);
        return;
      }
      setLocStatus(geoErrorMessage(err), true);
      showToast('Could not get your location');
    }, opts);
  }
  document.getElementById('getLocationBtn').addEventListener('click', function(){ handleLocation(false); });
  document.getElementById('retryLocBtn').addEventListener('click', function(){ handleLocation(false); });
  document.getElementById('sosShareLoc').addEventListener('click', function(){
    location.hash = '#location';
    setTimeout(function(){ handleLocation(false); }, 150);
  });

  /* Proactively surface a blocked-permission hint before the user even taps */
  function checkGeoPermission(){
    const hint = document.getElementById('locPermHint');
    if(!hint) return;
    if(!isSecureCtx()){
      hint.textContent = 'This page needs to be loaded over https:// for location sharing to work.';
      hint.style.display = '';
      return;
    }
    if(!navigator.permissions || !navigator.permissions.query){ return; }
    navigator.permissions.query({name:'geolocation'}).then(function(status){
      function render(){
        if(status.state === 'denied'){
          hint.textContent = "Location is currently blocked for this site. Allow it in your browser's site settings to share your position.";
          hint.style.display = '';
        } else {
          hint.style.display = 'none';
        }
      }
      render();
      status.onchange = render;
    }).catch(function(){ /* Permissions API not supported for geolocation on this browser (e.g. some iOS Safari versions) — ignore */ });
  }
  checkGeoPermission();

  function legacyCopy(text){
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    ta.style.top = '0';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    let ok = false;
    try{ ok = document.execCommand('copy'); }catch(e){ ok = false; }
    document.body.removeChild(ta);
    return ok;
  }
  document.getElementById('copyLocBtn').addEventListener('click', function(){
    const text = document.getElementById('locLinkBox').textContent;
    if(!text) return;
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){ showToast('Map link copied'); }).catch(function(){
        showToast(legacyCopy(text) ? 'Map link copied' : 'Could not copy — select the link manually');
      });
    } else {
      showToast(legacyCopy(text) ? 'Map link copied' : 'Could not copy — select the link manually');
    }
  });
  document.getElementById('shareLocBtn').addEventListener('click', function(){
    const text = document.getElementById('locLinkBox').textContent;
    if(!text) return;
    if(navigator.share){
      navigator.share({title:'My location — Triple J Alert System', text:'Here is my current location:', url:text}).catch(()=>{});
    } else if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){ showToast('Sharing not supported — link copied instead'); });
    } else {
      showToast(legacyCopy(text) ? 'Sharing not supported — link copied instead' : 'Could not share or copy — select the link manually');
    }
  });

  /* ---------------- REPORT FORM ---------------- */
  document.getElementById('reportForm').addEventListener('submit', function(e){
    e.preventDefault();
    showToast('Report submitted — MDRRMO has been notified');
    this.reset();
  });

  /* ---------------- OFFLINE DETECTION ---------------- */
  function updateOffline(){
    document.getElementById('offlineBanner').classList.toggle('show', !navigator.onLine);
  }
  window.addEventListener('online', updateOffline);
  window.addEventListener('offline', updateOffline);
  updateOffline();

  /* ---------------- INIT ---------------- */
  function refreshAllRenders(){
    renderQuickAccess();
    filterAndRenderDashboard();
    renderSosList();
    renderContacts();
  }

  renderChips();
  renderTips();
  refreshAllRenders();
  route();

})();
